// Differential tests for uos/rt/string.hpp. Every expected value between the
// generated-vectors markers was produced by Bun 1.4.0 (the oracle); the WTF-8 cases
// at the end pin the storage convention of docs/rt/text.md, which has no JS oracle.
#include "uos/rt/string.hpp"
#include "uos/rt/test.hpp"

#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <limits>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <vector>

using namespace std::string_view_literals;
namespace rt = uos::rt;

namespace {
  constexpr double NaN = std::numeric_limits<double>::quiet_NaN();
  constexpr double Inf = std::numeric_limits<double>::infinity();

  bool sameNumber(double a, double b) { return (std::isnan(a) && std::isnan(b)) || a == b; }
  int sign(int value) { return value < 0 ? -1 : value > 0 ? 1 : 0; }

  template <class A, class B>
  void rowEqual(const A& actual, const B& expected, const char* text, std::size_t row, int line) {
    if (!(actual == expected)) {
      ::uos::rt::test::report(__FILE__, line,
        "row " + std::to_string(row) + ": " + text + "\n      actual:   " + ::uos::rt::test::show(actual) + "\n      expected: " + ::uos::rt::test::show(expected), false);
    }
  }
  void rowTrue(bool condition, const char* text, std::size_t row, int line) {
    if (!condition) ::uos::rt::test::report(__FILE__, line, "row " + std::to_string(row) + ": expected " + text, false);
  }

  // FNV-1a over bytes, as the generator computed it.
  void fnv(std::uint32_t& state, std::string_view bytes) {
    for (const char byte : bytes) {
      state ^= static_cast<unsigned char>(byte);
      state *= 16777619u;
    }
  }

  // "Name: message" of the rt::JsError the call throws, or "(no error)".
  template <class F>
  std::string thrownText(F&& call) {
    try {
      (void)call();
    } catch (const rt::JsError& error) {
      return error.toString();
    }
    return "(no error)";
  }
}

#define ROW_EQ(row, actual, expected) rowEqual((actual), (expected), #actual, (row), __LINE__)
#define ROW_TRUE(row, condition) rowTrue((condition), #condition, (row), __LINE__)

